/* Exit codes, as AcquaThermoNet and RoomSense (for the restart loop of the
 * package start.sh): 0 = stopped on purpose (SIGTERM/SIGINT or window
 * closed), EXIT_ALREADY_RUNNING = another instance runs (no restart),
 * anything else or a signal = crash (restarted) */
#define EXIT_ALREADY_RUNNING    3



